window.READING_REVIEW_DATA = {"items":[{"id":"rentals-v-1","term":"property","type":"word","sourceOrder":1,"zh":"房产；房屋","pos":"n.","ipa":"ˈprɒpəti","stars":2,"note":"财产；性质、特性；property market 房地产市场；property rights 财产权；也可指“性质、属性”，如 chemical properties","paragraph":"听力原文","examples":[{"en":"You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service.","zh":"你将听到一位想租公寓的男士与房屋租赁服务机构的一名中介之间的电话对话。","source":"original","number":1},{"en":"Good morning, AA Property.","zh":"早上好，这里是AA房产。","source":"original","number":4},{"en":"Well, now I'll take some details about the kind of property you're looking for.","zh":"现在我来记录一些有关您所寻找的房产类型的信息。","source":"original","number":34}]},{"id":"rentals-v-2","term":"rent","type":"word","sourceOrder":2,"zh":"租房；租金；租用","pos":"v./n.","ipa":"rent","stars":1,"note":"出租、承租；rent an apartment；monthly rent；作动词还可指“出租”（语境辨析）","paragraph":"听力原文","examples":[{"en":"You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service.","zh":"你将听到一位想租公寓的男士与房屋租赁服务机构的一名中介之间的电话对话。","source":"original","number":1},{"en":"I'm looking for an apartment to rent.","zh":"我正在找一套要租的公寓。","source":"original","number":8},{"en":"And what's the maximum rent you'd be prepared to pay?","zh":"您愿意支付的最高租金是多少？","source":"original","number":44}]},{"id":"rentals-v-3","term":"apartment","type":"word","sourceOrder":3,"zh":"公寓；公寓（美式常用）","pos":"n.","ipa":"əˈpɑːtmənt","stars":2,"note":"套房、住宅单元；apartment block 公寓楼；英国日常口语常用 flat","paragraph":"听力原文","examples":[{"en":"You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service.","zh":"你将听到一位想租公寓的男士与房屋租赁服务机构的一名中介之间的电话对话。","source":"original","number":1},{"en":"I'm looking for an apartment to rent.","zh":"我正在找一套要租的公寓。","source":"original","number":8},{"en":"You said you're looking for an apartment, is that right?","zh":"您说想找一套公寓，是吗？","source":"original","number":35}]},{"id":"rentals-v-4","term":"agent","type":"word","sourceOrder":4,"zh":"中介；（房产）中介","pos":"n.","ipa":"ˈeɪdʒənt","stars":2,"note":"代理人；作用因素；travel agent 旅行代理；estate agent 房产中介；也可指“作用因素”，如 a chemical agent","paragraph":"听力原文","examples":[{"en":"You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service.","zh":"你将听到一位想租公寓的男士与房屋租赁服务机构的一名中介之间的电话对话。","source":"original","number":1},{"en":"The agent replied straight away.","zh":"中介立即回复了。","source":"supplemental"},{"en":"The agent put down our requirements.","zh":"中介记下了我们的需求。","source":"supplemental"}]},{"id":"rentals-v-5","term":"present","type":"word","sourceOrder":5,"zh":"目前的；现在的","pos":"adj.","ipa":"ˈprezənt","stars":2,"note":"出席的；现存的。另作名词“礼物”；单独朗读用辅助短语限定本文形容词读音；单词听写只写核心词。；the present situation 目前的形势；作 n. 为“礼物”；/prɪˈzent/ 作 v. 表“呈现”","paragraph":"听力原文","examples":[{"en":"And can I have your present address, please?","zh":"请问能告诉我您目前的住址吗？","source":"original","number":17},{"en":"Well, we're staying with friends at present, so the address is three five four Forest Road.","zh":"我们现在暂住在朋友家，所以地址是354 Forest Road。","source":"original","number":18},{"en":"I'm a dentist and my wife's a teacher, but she's at home at present looking after the children.","zh":"我是牙医，我妻子是教师，但她目前在家照顾孩子。","source":"original","number":30}]},{"id":"rentals-v-6","term":"detail","type":"word","sourceOrder":6,"zh":"具体信息；细节；信息条目","pos":"n.","ipa":"ˈdiːteɪl","stars":2,"note":"细节；provide details 提供详情；此处 take details 是“登记信息”","paragraph":"听力原文","examples":[{"en":"I'll just take some personal details, if I may.","zh":"我想先记录一些个人信息，可以吗？","source":"original","number":13},{"en":"Well, now I'll take some details about the kind of property you're looking for.","zh":"现在我来记录一些有关您所寻找的房产类型的信息。","source":"original","number":34},{"en":"The receptionist took my personal details.","zh":"前台登记了我的个人信息。","source":"supplemental"}]},{"id":"rentals-v-7","term":"contact","type":"word","sourceOrder":7,"zh":"联系方式；联系电话；联系信息","pos":"n.","ipa":"ˈkɒntækt","stars":3,"note":"接触；联系人；contact details / contact number；作 v. 通常重音后移 /kənˈtækt/","paragraph":"听力原文","examples":[{"en":"And a contact phone number.","zh":"再请提供联系电话。","source":"original","number":24},{"en":"Please leave a contact phone number.","zh":"请留下联系电话。","source":"supplemental"},{"en":"Is this your current contact phone number?","zh":"这是你目前的联系电话吗？","source":"supplemental"}]},{"id":"rentals-v-8","term":"postcode","type":"word","sourceOrder":8,"zh":"邮政编码；邮政编码（post code / postcode）","pos":"n.","ipa":"ˈpəʊstkəʊd","stars":3,"note":"常见于英国地址填空；postcode area 邮编区域；美式英语常说 ZIP code","paragraph":"听力原文","examples":[{"en":"I'm afraid I don't know the postcode.","zh":"恐怕我不知道邮政编码。","source":"original","number":22}]},{"id":"rentals-v-9","term":"occupation","type":"word","sourceOrder":9,"zh":"职业","pos":"n.","ipa":"ˌɒkjʊˈpeɪʃən","stars":4,"note":"占据、占领；occupation status 职业状况；也可指“占据；占领”","paragraph":"听力原文","memory":{"parts":"occupy（占据／从事）→ occupation","tip":"用 occupy 与 occupation 词族联结记忆；登记表里 occupation 指职业，不是占领。","family":"occupy, occupation, occupational"},"examples":[{"en":"And if I could just ask your occupation.","zh":"如果方便的话，我想问一下您的职业。","source":"original","number":28},{"en":"So I'll just put your occupation.","zh":"那我就只登记您的职业。","source":"original","number":32}]},{"id":"rentals-v-10","term":"dentist","type":"word","sourceOrder":10,"zh":"牙医","pos":"n.","ipa":"ˈdentɪst","stars":2,"note":"职业类高频词；go to the dentist 看牙医；与 dental /ˈdentl/（牙科的）同族","paragraph":"听力原文","examples":[{"en":"I'm a dentist and my wife's a teacher, but she's at home at present looking after the children.","zh":"我是牙医，我妻子是教师，但她目前在家照顾孩子。","source":"original","number":30}]},{"id":"rentals-v-11","term":"furnished","type":"word","sourceOrder":11,"zh":"配有家具的；带家具的","pos":"adj.","ipa":"ˈfɜːnɪʃt","stars":3,"note":"furnish 还可指提供资料；fully furnished 设施家具齐全；unfurnished 表不带家具","paragraph":"听力原文","examples":[{"en":"And did you want it furnished?","zh":"那您希望是带家具的吗？","source":"original","number":40},{"en":"Both of them are furnished.","zh":"两间都带家具。","source":"supplemental"}]},{"id":"rentals-v-12","term":"unfurnished","type":"word","sourceOrder":12,"zh":"不带家具的；无家具配置的","pos":"adj.","ipa":"ʌnˈfɜːnɪʃt","stars":4,"note":"furnished 的反义词；an unfurnished apartment；un- 反义前缀；和 unfinished 不要混淆","paragraph":"听力原文","memory":{"parts":"un-（不）＋ furnished（带家具的）","tip":"否定前缀 un- 改变答案；不要听到提问 furnished 就停笔。","family":"furnish, furnished, unfurnished"},"examples":[{"en":"No, unfurnished.","zh":"不，要不带家具的。","source":"original","number":41},{"en":"An unfurnished flat offers quite a bit more choice.","zh":"不带家具的公寓选择更多。","source":"supplemental"}]},{"id":"rentals-v-13","term":"maximum","type":"word","sourceOrder":13,"zh":"最高的；上限；最大的；最高限额","pos":"adj./n.","ipa":"ˈmæksɪməm","stars":4,"note":"最大值；maximum rent 最高租金；反义 minimum 最低限额","paragraph":"听力原文","memory":{"parts":"maximum ↔ minimum（成对记忆）","tip":"最高限额是 maximum；希望低于600，但合适时可出650，二者角色不同。","family":"maximum, minimum"},"examples":[{"en":"And what's the maximum rent you'd be prepared to pay?","zh":"您愿意支付的最高租金是多少？","source":"original","number":44}]},{"id":"rentals-v-14","term":"definite","type":"word","sourceOrder":14,"zh":"明确的；确定的","pos":"adj.","ipa":"ˈdefɪnət","stars":3,"note":"确定的、肯定的；definite requirement 明确要求；definitely 为副词，表示“肯定地”","paragraph":"听力原文","examples":[{"en":"So do you have any other definite requirements?","zh":"还有其他明确、必须满足的要求吗？","source":"original","number":47}]},{"id":"rentals-v-15","term":"requirement","type":"word","sourceOrder":15,"zh":"要求；条件","pos":"n.","ipa":"rɪˈkwaɪəmənt","stars":4,"note":"必要条件；meet requirements 满足要求；常搭配 entry / legal / minimum","paragraph":"听力原文","memory":{"parts":"require（要求）＋-ment","tip":"用 requirements、meet requirements 作为整体记，指必须满足的条件。","family":"require, requirement, required"},"examples":[{"en":"So do you have any other definite requirements?","zh":"还有其他明确、必须满足的要求吗？","source":"original","number":47},{"en":"The agent put down our requirements.","zh":"中介记下了我们的需求。","source":"supplemental"}]},{"id":"rentals-v-16","term":"double","type":"word","sourceOrder":16,"zh":"双人的；双人房","pos":"adj./n.","ipa":"ˈdʌbəl","stars":2,"note":"两倍的；翻倍；a double room；double bedroom；名词复数 doubles；也可表“两倍”","paragraph":"听力原文","examples":[{"en":"Well, coming back to the bedrooms, they have to be doubles, both of them.","zh":"说回卧室，两间都必须是双人卧室。","source":"original","number":48},{"en":"Both rooms have to be doubles.","zh":"两间房都必须是双人间。","source":"supplemental"}]},{"id":"rentals-v-17","term":"assume","type":"word","sourceOrder":17,"zh":"推测；假定","pos":"v.","ipa":"əˈsjuːm","stars":3,"note":"假设；承担职责；assume that...；不等于 confirm 确认","paragraph":"听力原文","examples":[{"en":"I assume you are if you're staying with friends.","zh":"我想既然您暂住在朋友家，应该想尽快搬入。","source":"original","number":53}]},{"id":"rentals-v-18","term":"earliest","type":"word","sourceOrder":18,"zh":"最早；最早的；最早地","pos":"adj./adv.","ipa":"ˈɜːliəst","stars":3,"note":"at the earliest 最早；at the earliest 最早；与 at the latest 最晚 对照","paragraph":"听力原文","examples":[{"en":"Well, it's October the seventeenth today, so we're probably looking at November the first at the earliest.","zh":"今天是10月17日，因此最早可能是11月1日。","source":"original","number":55},{"en":"The flat is available next Monday at the earliest.","zh":"这套公寓最早下周一可入住。","source":"supplemental"},{"en":"We can view it at the earliest on Friday.","zh":"我们最早周五能看房。","source":"supplemental"}]},{"id":"rentals-v-19","term":"garage","type":"word","sourceOrder":19,"zh":"车库","pos":"n.","ipa":"ˈɡærɑːʒ","stars":3,"note":"汽车修理厂；a private garage 私人车库；也可指汽车维修店","paragraph":"听力原文","examples":[{"en":"Well, our last flat had a garage, but actually we never used it, so I'm not really worried about that.","zh":"之前的公寓有车库，但我们从未使用，所以我并不在意车库。","source":"original","number":60},{"en":"Do not worry about the garage.","zh":"不用担心车库。","source":"supplemental"},{"en":"A garage is not essential.","zh":"车库并非必要。","source":"supplemental"}]},{"id":"rentals-v-20","term":"balcony","type":"word","sourceOrder":20,"zh":"阳台","pos":"n.","ipa":"ˈbælkəni","stars":3,"note":"剧院楼座；have a balcony 带阳台；注意发音：前重音，非 /bælˈkəʊni/","paragraph":"听力原文","examples":[{"en":"But we'd like a balcony if possible.","zh":"但如果可以，我们想要一个阳台。","source":"original","number":61},{"en":"We would like a balcony if possible.","zh":"如果可以，我们想要阳台。","source":"supplemental"},{"en":"A balcony keeps the room from feeling shut in.","zh":"阳台让房间不那么封闭。","source":"supplemental"}]},{"id":"rentals-v-21","term":"converted","type":"word","sourceOrder":21,"zh":"改建的；改建后的","pos":"adj.","ipa":"kənˈvɜːtɪd","stars":4,"note":"已转换用途的；converted property 改造房屋；过去分词作定语","paragraph":"听力原文","memory":{"parts":"convert（改建）＋-ed","tip":"过去分词作定语，converted properties 是改建后的房屋。","family":"convert, conversion, converted"},"examples":[{"en":"It's only the converted properties that don't.","zh":"只有改建后的房产才可能没有阳台。","source":"original","number":65}]},{"id":"rentals-v-22","term":"alternative","type":"word","sourceOrder":22,"zh":"替代方案；替代的","pos":"n./adj.","ipa":"ɔːlˈtɜːnətɪv","stars":4,"note":"可供选择的；an alternative to sth；考点：A or B / either of those","paragraph":"听力原文","memory":{"parts":"alternate 词族 → alternative","tip":"用“另一个可行选择”的画面记替代方案；balcony 或 garden 任一即可。","family":"alternate, alternative, alternatively"},"examples":[{"en":"Would that be a possible alternative?","zh":"这个能作为替代选择吗？","source":"original","number":67},{"en":"A garden is a possible alternative.","zh":"花园是可行替代。","source":"supplemental"},{"en":"Could we discuss a possible alternative?","zh":"我们能讨论一个替代方案吗？","source":"supplemental"}]},{"id":"rentals-v-23","term":"transport","type":"word","sourceOrder":23,"zh":"交通；运输","pos":"n.","ipa":"ˈtrænspɔːt","stars":3,"note":"运输；public transport 公共交通；动词重音常后移 /trænˈspɔːt/","paragraph":"听力原文","examples":[{"en":"What about transport?","zh":"交通方面有什么要求？","source":"original","number":70},{"en":"I'd like to come back to the issue of transport.","zh":"我想重新讨论交通问题。","source":"supplemental"}]},{"id":"rentals-v-24","term":"parking","type":"word","sourceOrder":24,"zh":"停车；停车位/设施","pos":"n.","ipa":"ˈpɑːkɪŋ","stars":2,"note":"停车设施；off-street parking 路外停车；parking 与 park（公园）不同","paragraph":"听力原文","examples":[{"en":"Would you want off-street parking?","zh":"您需要路外停车位（不直接占用街道路边的停车位）吗？","source":"original","number":71},{"en":"No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible.","zh":"不，停车不重要，但如果能住在离车站不太远的地方就好。","source":"original","number":72},{"en":"I am not worried about parking.","zh":"我不在意停车问题。","source":"supplemental"}]},{"id":"rentals-v-25","term":"essential","type":"word","sourceOrder":25,"zh":"必需的；重要的","pos":"adj.","ipa":"ɪˈsenʃəl","stars":4,"note":"根本的、极其重要的；not essential 并非必要；作名词复数 essentials 指必需品","paragraph":"听力原文","memory":{"parts":"essence（本质）→ essential","tip":"由本质、核心联想到必需；not essential 明确表示不是硬性要求。","family":"essence, essential, essentially"},"examples":[{"en":"But it's not essential.","zh":"但这不是必需条件。","source":"original","number":73},{"en":"A garage is not essential.","zh":"车库并非必要。","source":"supplemental"},{"en":"Being near a station is not essential.","zh":"靠近车站不是硬性要求。","source":"supplemental"}]},{"id":"rentals-v-26","term":"lounge","type":"word","sourceOrder":26,"zh":"客厅；起居室、客厅","pos":"n.","ipa":"laʊndʒ","stars":3,"note":"休息室、候机室；a large lounge 宽敞起居室；机场也有 lounge（休息室）","paragraph":"听力原文","examples":[{"en":"You'll want a lounge.","zh":"您会需要一个起居室。","source":"original","number":77}]},{"id":"rentals-v-27","term":"separate","type":"word","sourceOrder":27,"zh":"独立的；分开的","pos":"adj.","ipa":"ˈsepərət","stars":3,"note":"分开的、不同的；单独朗读用辅助短语限定本文形容词读音；单词听写只写核心词。；separate dining room 独立餐厅；作动词读 /ˈsepəreɪt/","paragraph":"听力原文","examples":[{"en":"And will you want a separate dining room?","zh":"您是否需要一间独立餐厅？","source":"original","number":78},{"en":"A separate dining room is not essential.","zh":"独立餐厅并非必须。","source":"supplemental"}]},{"id":"rentals-v-28","term":"dining","type":"word","sourceOrder":28,"zh":"用餐；餐饮的；用餐的；进餐","pos":"n./adj.","ipa":"ˈdaɪnɪŋ","stars":3,"note":"dining room 餐厅；dining room 餐厅；来自 dine；不等于 kitchen 厨房","paragraph":"听力原文","examples":[{"en":"And will you want a separate dining room?","zh":"您是否需要一间独立餐厅？","source":"original","number":78},{"en":"A separate dining room is not essential.","zh":"独立餐厅并非必须。","source":"supplemental"},{"en":"The kitchen is large enough to accommodate a dining table.","zh":"厨房足够大，可以放下一张餐桌。","source":"supplemental"}]},{"id":"rentals-v-29","term":"tend","type":"word","sourceOrder":29,"zh":"往往、倾向于","pos":"v.","ipa":"tend","stars":3,"note":"照料、护理；tend to do sth 往往做；也可指“照料”，如 tend a garden","paragraph":"听力原文","examples":[{"en":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that.","zh":"我们通常在厨房吃饭，所以如果厨房足够大，能让我们在那里用餐，就很好。","source":"original","number":80},{"en":"We tend to eat in the kitchen.","zh":"我们通常在厨房吃饭。","source":"supplemental"},{"en":"Students tend to choose cheaper flats.","zh":"学生往往选便宜公寓。","source":"supplemental"}]},{"id":"rentals-v-30","term":"available","type":"word","sourceOrder":30,"zh":"可获得的","pos":"adj.","ipa":"əˈveɪləbəl","stars":4,"note":"有空的、可用的","paragraph":"词汇与语块","memory":{"parts":"avail 与 available（词族联想）","tip":"可用、可获得；房源 available 表示可供租用，unavailable 则相反。","family":"avail, available, availability"},"examples":[{"en":"The flat is available next Monday at the earliest.","zh":"这套公寓最早下周一可入住。","source":"supplemental"},{"en":"The property is not available at present.","zh":"这处房产目前无法租用。","source":"supplemental"},{"en":"The results won't be available until Friday at the earliest.","zh":"结果最早要到周五才能出来。","source":"supplemental"}]},{"id":"rentals-v-31","term":"rental","type":"word","sourceOrder":31,"zh":"租赁；租赁的","pos":"n./adj.","ipa":"ˈrentl","stars":3,"note":"rental agreement 租约；rental income 租金收入；car rental 指汽车租赁","paragraph":"听力原文","examples":[{"en":"You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service.","zh":"你将听到一位想租公寓的男士与房屋租赁服务机构的一名中介之间的电话对话。","source":"original","number":1}]},{"id":"rentals-v-32","term":"personal","type":"word","sourceOrder":32,"zh":"个人的","pos":"adj.","ipa":"ˈpɜːsənl","stars":2,"note":"personal information 个人信息；personal opinion 个人观点","paragraph":"听力原文","examples":[{"en":"I'll just take some personal details, if I may.","zh":"我想先记录一些个人信息，可以吗？","source":"original","number":13},{"en":"The receptionist took my personal details.","zh":"前台登记了我的个人信息。","source":"supplemental"},{"en":"May I take a few personal details?","zh":"我能登记几项个人信息吗？","source":"supplemental"}]},{"id":"rentals-v-33","term":"address","type":"word","sourceOrder":33,"zh":"地址","pos":"n.","ipa":"əˈdres","stars":2,"note":"residential address 居住地址；作 v. /əˈdres/ 可指“处理问题”；address an issue","paragraph":"听力原文","examples":[{"en":"And can I have your present address, please?","zh":"请问能告诉我您目前的住址吗？","source":"original","number":17},{"en":"Well, we're staying with friends at present, so the address is three five four Forest Road.","zh":"我们现在暂住在朋友家，所以地址是354 Forest Road。","source":"original","number":18},{"en":"Please make a note of the address.","zh":"请记下地址。","source":"supplemental"}]},{"id":"rentals-v-34","term":"stay","type":"word","sourceOrder":34,"zh":"暂住；停留","pos":"v.","ipa":"steɪ","stars":2,"note":"stay with relatives 借住亲戚家；be staying 强调临时状况","paragraph":"听力原文","examples":[{"en":"Well, we're staying with friends at present, so the address is three five four Forest Road.","zh":"我们现在暂住在朋友家，所以地址是354 Forest Road。","source":"original","number":18},{"en":"Well, we'd like to stay under six hundred pounds if possible, but we could go up to six hundred and fifty for the right place.","zh":"我们希望尽量控制在600英镑以下，但房子合适的话最多可以到650英镑。","source":"original","number":45},{"en":"I assume you are if you're staying with friends.","zh":"我想既然您暂住在朋友家，应该想尽快搬入。","source":"original","number":53}]},{"id":"rentals-v-35","term":"number","type":"word","sourceOrder":35,"zh":"号码","pos":"n.","ipa":"ˈnʌmbə","stars":1,"note":"phone number 电话号码；也可指数量，如 a number of","paragraph":"听力原文","examples":[{"en":"And a contact phone number.","zh":"再请提供联系电话。","source":"original","number":24},{"en":"Please leave a contact phone number.","zh":"请留下联系电话。","source":"supplemental"},{"en":"Is this your current contact phone number?","zh":"这是你目前的联系电话吗？","source":"supplemental"}]},{"id":"rentals-v-36","term":"teacher","type":"word","sourceOrder":36,"zh":"教师","pos":"n.","ipa":"ˈtiːtʃə","stars":1,"note":"primary-school teacher 小学教师；与 teach / taught / taught 同族","paragraph":"听力原文","examples":[{"en":"I'm a dentist and my wife's a teacher, but she's at home at present looking after the children.","zh":"我是牙医，我妻子是教师，但她目前在家照顾孩子。","source":"original","number":30}]},{"id":"rentals-v-37","term":"look after","type":"phrase","sourceOrder":37,"zh":"照顾","pos":"phr. v.","ipa":"lʊk ˈɑːftə","stars":3,"note":"look after children；也可指照看事务或事物；讲义形式：look after。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"I'm a dentist and my wife's a teacher, but she's at home at present looking after the children.","zh":"我是牙医，我妻子是教师，但她目前在家照顾孩子。","source":"original","number":30},{"en":"He looks after his younger brother.","zh":"他照顾弟弟。","source":"supplemental"},{"en":"Who will look after the children?","zh":"谁来照顾孩子？","source":"supplemental"},{"en":"She looked after the house while we were away.","zh":"我们不在时她负责照看房子。","source":"supplemental"}]},{"id":"rentals-v-38","term":"bedroom","type":"word","sourceOrder":38,"zh":"卧室","pos":"n.","ipa":"ˈbedruːm","stars":1,"note":"two-bedroom flat 两居室；形容词复合修饰语用单数 two-bedroom","paragraph":"听力原文","examples":[{"en":"So how many bedrooms do you want?","zh":"那么您想要几间卧室？","source":"original","number":38},{"en":"Well, coming back to the bedrooms, they have to be doubles, both of them.","zh":"说回卧室，两间都必须是双人卧室。","source":"original","number":48},{"en":"Can we come back to the bedrooms?","zh":"能再谈谈卧室吗？","source":"supplemental"}]},{"id":"rentals-v-39","term":"choice","type":"word","sourceOrder":39,"zh":"选择范围；选项","pos":"n.","ipa":"tʃɔɪs","stars":2,"note":"have more choice 有更多选择；“选择范围”时常为不可数用法","paragraph":"听力原文","examples":[{"en":"Well, that gives you quite a bit more choice, so that's good.","zh":"这样会让您有更多选择，所以不错。","source":"original","number":43},{"en":"An unfurnished flat offers quite a bit more choice.","zh":"不带家具的公寓选择更多。","source":"supplemental"}]},{"id":"rentals-v-40","term":"prefer","type":"word","sourceOrder":40,"zh":"更喜欢；偏好","pos":"v.","ipa":"prɪˈfɜː","stars":3,"note":"prefer A to B；would have preferred＝原本更希望","paragraph":"听力原文","examples":[{"en":"Well, I'd have preferred something in October, but okay, let's put that date down for now.","zh":"我原本更希望10月份，但好吧，先把那个日期记下来。","source":"original","number":57}]},{"id":"rentals-v-41","term":"prepare","type":"word","sourceOrder":41,"zh":"准备","pos":"v.","ipa":"prɪˈpeə","stars":3,"note":"be prepared to pay 愿意付钱；be prepared to 在这里并非只指事先做准备","paragraph":"听力原文","examples":[{"en":"And what's the maximum rent you'd be prepared to pay?","zh":"您愿意支付的最高租金是多少？","source":"original","number":44}]},{"id":"rentals-v-42","term":"under","type":"word","sourceOrder":42,"zh":"低于（金额）","pos":"prep.","ipa":"ˈʌndə","stars":2,"note":"under £600 不到600英镑；还可表示“在……管理之下”","paragraph":"听力原文","examples":[{"en":"Well, we'd like to stay under six hundred pounds if possible, but we could go up to six hundred and fifty for the right place.","zh":"我们希望尽量控制在600英镑以下，但房子合适的话最多可以到650英镑。","source":"original","number":45},{"en":"We hope to stay under our budget.","zh":"我们希望不超过预算。","source":"supplemental"},{"en":"Try to stay under £800 a month.","zh":"尽量把月租控制在800英镑以下。","source":"supplemental"}]},{"id":"rentals-v-43","term":"note","type":"word","sourceOrder":43,"zh":"记录；便条","pos":"n./v.","ipa":"nəʊt","stars":1,"note":"make a note of...；还可表示“语气；音符；注意到”","paragraph":"听力原文","examples":[{"en":"Okay, I'll make a note of that.","zh":"好的，我会把它记录下来。","source":"original","number":49},{"en":"That might be difficult, but I'll make a note of it anyway.","zh":"这也许有点难满足，但我还是会记下来。","source":"original","number":81},{"en":"Make a note of the viewing time.","zh":"记下看房时间。","source":"supplemental"}]},{"id":"rentals-v-44","term":"straightaway","type":"word","sourceOrder":44,"zh":"立即；马上","pos":"adv.","ipa":"ˌstreɪtəˈweɪ","stars":3,"note":"do sth straight away；也可分写 straight away；语境听写为分写 straight away。","paragraph":"听力原文","examples":[{"en":"So are you looking for something straight away?","zh":"那么，您想立刻入住吗？","source":"original","number":52}]},{"id":"rentals-v-45","term":"October","type":"word","sourceOrder":45,"zh":"十月","pos":"n.","ipa":"ɒkˈtəʊbə","stars":2,"note":"17 October / October 17；月份专名首字母大写","paragraph":"听力原文","examples":[{"en":"Well, it's October the seventeenth today, so we're probably looking at November the first at the earliest.","zh":"今天是10月17日，因此最早可能是11月1日。","source":"original","number":55},{"en":"Well, I'd have preferred something in October, but okay, let's put that date down for now.","zh":"我原本更希望10月份，但好吧，先把那个日期记下来。","source":"original","number":57}]},{"id":"rentals-v-46","term":"November","type":"word","sourceOrder":46,"zh":"十一月","pos":"n.","ipa":"nəʊˈvembə","stars":2,"note":"1 November / November 1；易与 October 混淆；抓最终确认日期","paragraph":"听力原文","examples":[{"en":"Well, it's October the seventeenth today, so we're probably looking at November the first at the earliest.","zh":"今天是10月17日，因此最早可能是11月1日。","source":"original","number":55},{"en":"Let us put down 1 November.","zh":"我们先记11月1日。","source":"supplemental"},{"en":"We are looking at a move in November.","zh":"我们考虑十一月搬家。","source":"supplemental"}]},{"id":"rentals-v-47","term":"modern","type":"word","sourceOrder":47,"zh":"现代的","pos":"adj.","ipa":"ˈmɒdn","stars":2,"note":"modern apartment 现代公寓；反义 older/traditional","paragraph":"听力原文","examples":[{"en":"You'll find most modern apartments do have one.","zh":"您会发现大多数现代公寓确实有阳台。","source":"original","number":64}]},{"id":"rentals-v-48","term":"convert","type":"word","sourceOrder":48,"zh":"改建；转换","pos":"v.","ipa":"kənˈvɜːt","stars":4,"note":"convert a building into flats；也可指货币兑换；单位换算","paragraph":"听力原文","memory":{"parts":"convert → conversion（词族）","tip":"用 convert a building into flats 记改建；转换用途不必然代表迁移。","family":"convert, conversion, converted"},"examples":[{"en":"It's only the converted properties that don't.","zh":"只有改建后的房产才可能没有阳台。","source":"original","number":65}]},{"id":"rentals-v-49","term":"garden","type":"word","sourceOrder":49,"zh":"花园","pos":"n.","ipa":"ˈɡɑːdn","stars":1,"note":"have use of a garden；在英式房源描述中可能是共享花园","paragraph":"听力原文","examples":[{"en":"But of course, if you're in an older property, you might have use of a garden.","zh":"不过如果住在较旧的房屋，您也许可以使用花园。","source":"original","number":66},{"en":"Tenants have use of a shared garden.","zh":"租客可以使用共享花园。","source":"supplemental"},{"en":"A garden is a possible alternative.","zh":"花园是可行替代。","source":"supplemental"}]},{"id":"rentals-v-50","term":"either","type":"word","sourceOrder":50,"zh":"两者之中任意一个","pos":"pron./det.","ipa":"ˈaɪðə","stars":3,"note":"either of those 两者任一；either...or...；英式读音也有 /ˈiːðə/","paragraph":"听力原文","examples":[{"en":"Either of those would be good.","zh":"这两种有任何一种都可以。","source":"original","number":69},{"en":"Either of those dates is fine.","zh":"两个日期哪天都行。","source":"supplemental"},{"en":"Either of those rooms would work.","zh":"两个房间任选其一都可以。","source":"supplemental"}]},{"id":"rentals-v-51","term":"off-street","type":"word","sourceOrder":51,"zh":"不占街道路边的；路外的","pos":"adj.","ipa":"ˌɒf ˈstriːt","stars":3,"note":"off-street parking；相对 on-street parking 路边停车","paragraph":"听力原文","examples":[{"en":"Would you want off-street parking?","zh":"您需要路外停车位（不直接占用街道路边的停车位）吗？","source":"original","number":71},{"en":"The building offers off-street parking.","zh":"这栋楼提供非路边停车位。","source":"supplemental"},{"en":"Off-street parking is included in the rent.","zh":"租金包含专用停车位。","source":"supplemental"}]},{"id":"rentals-v-52","term":"matter","type":"word","sourceOrder":52,"zh":"要紧；重要","pos":"v./n.","ipa":"ˈmætə","stars":3,"note":"It doesn’t matter. 没关系；作 n. 指“事情/物质”，如 a serious matter","paragraph":"听力原文","examples":[{"en":"No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible.","zh":"不，停车不重要，但如果能住在离车站不太远的地方就好。","source":"original","number":72},{"en":"Location matters for the right place.","zh":"找到合适房子时位置很重要。","source":"supplemental"}]},{"id":"rentals-v-53","term":"station","type":"word","sourceOrder":53,"zh":"车站","pos":"n.","ipa":"ˈsteɪʃn","stars":2,"note":"near a station 靠近车站；也可指广播电台、工作站","paragraph":"听力原文","examples":[{"en":"No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible.","zh":"不，停车不重要，但如果能住在离车站不太远的地方就好。","source":"original","number":72},{"en":"The flat is not too far from a station.","zh":"这套房离车站不太远。","source":"supplemental"},{"en":"Being near a station is not essential.","zh":"靠近车站不是硬性要求。","source":"supplemental"}]},{"id":"rentals-v-54","term":"bike","type":"word","sourceOrder":54,"zh":"自行车","pos":"n.","ipa":"baɪk","stars":1,"note":"ride a bike 骑车；口语常见 bicycle 缩写","paragraph":"听力原文","examples":[{"en":"I've got a bike.","zh":"我有自行车。","source":"original","number":74}]},{"id":"rentals-v-55","term":"kitchen","type":"word","sourceOrder":55,"zh":"厨房","pos":"n.","ipa":"ˈkɪtʃɪn","stars":1,"note":"large kitchen / eat in the kitchen；厨房能否吃饭是本题真正所需","paragraph":"听力原文","examples":[{"en":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that.","zh":"我们通常在厨房吃饭，所以如果厨房足够大，能让我们在那里用餐，就很好。","source":"original","number":80},{"en":"The kitchen has to be large.","zh":"厨房必须够大。","source":"supplemental"},{"en":"We tend to eat in the kitchen.","zh":"我们通常在厨房吃饭。","source":"supplemental"}]},{"id":"rentals-v-56","term":"enough","type":"word","sourceOrder":56,"zh":"足够","pos":"adv./det.","ipa":"ɪˈnʌf","stars":2,"note":"large enough to do sth；置于形容词之后：large enough","paragraph":"听力原文","examples":[{"en":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that.","zh":"我们通常在厨房吃饭，所以如果厨房足够大，能让我们在那里用餐，就很好。","source":"original","number":80},{"en":"That is enough information for now.","zh":"暂时这些信息就够了。","source":"supplemental"},{"en":"The kitchen is large enough for us to eat in.","zh":"厨房够大，可以在里面吃饭。","source":"supplemental"}]},{"id":"rentals-v-57","term":"possible","type":"word","sourceOrder":57,"zh":"可能的；可行的","pos":"adj.","ipa":"ˈpɒsəbl","stars":2,"note":"if possible 如果可以；与 impossible 相对；not essential 非必要","paragraph":"听力原文","examples":[{"en":"Well, we'd like to stay under six hundred pounds if possible, but we could go up to six hundred and fifty for the right place.","zh":"我们希望尽量控制在600英镑以下，但房子合适的话最多可以到650英镑。","source":"original","number":45},{"en":"Well, as soon as possible, yes.","zh":"是的，越快越好。","source":"original","number":54},{"en":"But we'd like a balcony if possible.","zh":"但如果可以，我们想要一个阳台。","source":"original","number":61}]},{"id":"rentals-v-58","term":"profession","type":"word","sourceOrder":58,"zh":"需要专门训练的职业","pos":"n.","ipa":"prəˈfeʃn","stars":4,"note":"讲义对照：occupation 泛指职业；profession 偏专业职业。牙医和教师是本篇实例。","paragraph":"词汇与语块","memory":{"parts":"profession → professional（词族）","tip":"从 professional（专业的）回记 profession；牙医、教师属于需要专门训练的职业。","family":"profession, professional"},"examples":[{"en":"Dentistry is a profession that requires specialist training.","zh":"牙科是一项需要专门训练的职业。","source":"supplemental"}]},{"id":"rentals-v-59","term":"information","type":"word","sourceOrder":59,"zh":"信息","pos":"n.","ipa":"ˌɪnfəˈmeɪʃn","stars":3,"note":"personal information 个人信息；不可数，不说 informations","paragraph":"词汇与语块","examples":[{"en":"The information has to be accurate.","zh":"信息必须准确。","source":"supplemental"},{"en":"That is enough information for now.","zh":"暂时这些信息就够了。","source":"supplemental"}]},{"id":"rentals-v-60","term":"accommodation","type":"word","sourceOrder":60,"zh":"住宿；住处","pos":"n.","ipa":"əˌkɒməˈdeɪʃn","stars":5,"note":"find accommodation 寻找住处；英式英语通常不可数","paragraph":"词汇与语块","memory":{"parts":"accommodate（提供住处）→ accommodation","tip":"用动词与名词成对记；双 c、双 m，英式通常作不可数名词。","family":"accommodate, accommodation"},"examples":[{"en":"She's looking for accommodation near the university.","zh":"她正在找大学附近的住所。","source":"supplemental"}]},{"id":"rentals-p-1","term":"look for","type":"phrase","sourceOrder":61,"zh":"寻找；重在寻找过程","pos":"短语／语块","ipa":"lʊk fɔː","stars":2,"note":"讲义形式：look for。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"I'm looking for an apartment to rent.","zh":"我正在找一套要租的公寓。","source":"original","number":8},{"en":"I am looking for a flat near campus.","zh":"我在找一套靠近校园的公寓。","source":"supplemental"},{"en":"They are looking for a cheaper place.","zh":"他们正在找更便宜的住处。","source":"supplemental"},{"en":"What are you looking for in a home?","zh":"你对住房有什么要求？","source":"supplemental"}]},{"id":"rentals-p-2","term":"an apartment to rent","type":"phrase","sourceOrder":62,"zh":"一套待租的公寓","pos":"短语／语块","ipa":"ən əˈpɑːtmənt tə rent","stars":2,"note":"讲义形式：an apartment to rent。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"I'm looking for an apartment to rent.","zh":"我正在找一套要租的公寓。","source":"original","number":8},{"en":"We saw an apartment to rent online.","zh":"我们在网上看到一套待租公寓。","source":"supplemental"},{"en":"Do you have any apartments to rent?","zh":"你们有房子出租吗？","source":"supplemental"},{"en":"The agency has two apartments to rent.","zh":"中介有两套待租公寓。","source":"supplemental"}]},{"id":"rentals-p-3","term":"take personal details","type":"phrase","sourceOrder":63,"zh":"登记个人信息","pos":"短语／语块","ipa":"teɪk ˈpɜːsənl ˈdiːteɪlz","stars":4,"note":"讲义形式：take personal details。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"I'll just take some personal details, if I may.","zh":"我想先记录一些个人信息，可以吗？","source":"original","number":13},{"en":"The receptionist took my personal details.","zh":"前台登记了我的个人信息。","source":"supplemental"},{"en":"May I take a few personal details?","zh":"我能登记几项个人信息吗？","source":"supplemental"},{"en":"They take personal details before the viewing.","zh":"看房前他们会先登记个人信息。","source":"supplemental"}]},{"id":"rentals-p-4","term":"at present","type":"phrase","sourceOrder":64,"zh":"目前；现在","pos":"短语／语块","ipa":"æt ˈprezənt","stars":2,"note":"讲义形式：at present。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, we're staying with friends at present, so the address is three five four Forest Road.","zh":"我们现在暂住在朋友家，所以地址是354 Forest Road。","source":"original","number":18},{"en":"At present, we live with relatives.","zh":"我们目前与亲戚同住。","source":"supplemental"},{"en":"The flat is unavailable at present.","zh":"这套公寓目前不可租。","source":"supplemental"},{"en":"At present, my wife works from home.","zh":"我妻子目前居家办公。","source":"supplemental"}]},{"id":"rentals-p-5","term":"stay with friends","type":"phrase","sourceOrder":65,"zh":"借住朋友家","pos":"短语／语块","ipa":"steɪ wɪð frendz","stars":2,"note":"讲义形式：stay with friends。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, we're staying with friends at present, so the address is three five four Forest Road.","zh":"我们现在暂住在朋友家，所以地址是354 Forest Road。","source":"original","number":18},{"en":"We stayed with friends during the move.","zh":"搬家期间我们借住朋友家。","source":"supplemental"},{"en":"She is staying with friends this week.","zh":"她本周住在朋友家。","source":"supplemental"},{"en":"You can stay with friends temporarily.","zh":"你可以暂时借住朋友家。","source":"supplemental"}]},{"id":"rentals-p-6","term":"contact phone number","type":"phrase","sourceOrder":66,"zh":"联系电话","pos":"短语／语块","ipa":"ˈkɒntækt fəʊn ˈnʌmbə","stars":2,"note":"讲义形式：contact phone number。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"And a contact phone number.","zh":"再请提供联系电话。","source":"original","number":24},{"en":"Please leave a contact phone number.","zh":"请留下联系电话。","source":"supplemental"},{"en":"Is this your current contact phone number?","zh":"这是你目前的联系电话吗？","source":"supplemental"},{"en":"The form asks for a contact phone number.","zh":"表格要求填写联系电话。","source":"supplemental"}]},{"id":"rentals-p-8","term":"make a note of","type":"phrase","sourceOrder":67,"zh":"记下","pos":"短语／语块","ipa":"meɪk ə nəʊt əv","stars":2,"note":"讲义形式：make a note of。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Okay, I'll make a note of that.","zh":"好的，我会把它记录下来。","source":"original","number":49},{"en":"Make a note of the viewing time.","zh":"记下看房时间。","source":"supplemental"},{"en":"I made a note of his phone number.","zh":"我记下了他的电话号码。","source":"supplemental"},{"en":"Please make a note of the address.","zh":"请记下地址。","source":"supplemental"}]},{"id":"rentals-p-9","term":"quite a bit more","type":"phrase","sourceOrder":68,"zh":"多出不少","pos":"短语／语块","ipa":"kwaɪt ə bɪt mɔː","stars":3,"note":"讲义形式：quite a bit more。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, that gives you quite a bit more choice, so that's good.","zh":"这样会让您有更多选择，所以不错。","source":"original","number":43},{"en":"This gives us quite a bit more flexibility.","zh":"这使我们灵活得多。","source":"supplemental"},{"en":"An unfurnished flat offers quite a bit more choice.","zh":"不带家具的公寓选择更多。","source":"supplemental"},{"en":"We need quite a bit more time.","zh":"我们还需要多得多的时间。","source":"supplemental"}]},{"id":"rentals-p-10","term":"be prepared to pay","type":"phrase","sourceOrder":69,"zh":"愿意支付","pos":"短语／语块","ipa":"biː prɪˈpeəd tə peɪ","stars":4,"note":"讲义形式：be prepared to pay。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"And what's the maximum rent you'd be prepared to pay?","zh":"您愿意支付的最高租金是多少？","source":"original","number":44},{"en":"I am prepared to pay £700 a month.","zh":"我愿意每月支付700英镑。","source":"supplemental"},{"en":"How much are you prepared to pay?","zh":"你愿意付多少钱？","source":"supplemental"},{"en":"They were prepared to pay a deposit.","zh":"他们愿意付押金。","source":"supplemental"}]},{"id":"rentals-p-11","term":"stay under","type":"phrase","sourceOrder":70,"zh":"保持在（预算）以下","pos":"短语／语块","ipa":"steɪ ˈʌndə","stars":3,"note":"讲义形式：stay under。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, we'd like to stay under six hundred pounds if possible, but we could go up to six hundred and fifty for the right place.","zh":"我们希望尽量控制在600英镑以下，但房子合适的话最多可以到650英镑。","source":"original","number":45},{"en":"We hope to stay under our budget.","zh":"我们希望不超过预算。","source":"supplemental"},{"en":"Try to stay under £800 a month.","zh":"尽量把月租控制在800英镑以下。","source":"supplemental"},{"en":"The total cost stayed under £1,000.","zh":"总费用没有超过1000英镑。","source":"supplemental"}]},{"id":"rentals-p-12","term":"go up to","type":"phrase","sourceOrder":71,"zh":"（金额/程度）最高可达","pos":"短语／语块","ipa":"ɡəʊ ʌp tə","stars":3,"note":"讲义形式：go up to。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, we'd like to stay under six hundred pounds if possible, but we could go up to six hundred and fifty for the right place.","zh":"我们希望尽量控制在600英镑以下，但房子合适的话最多可以到650英镑。","source":"original","number":45},{"en":"We could go up to £650 for the right flat.","zh":"房子合适我们最多可出650英镑。","source":"supplemental"},{"en":"The rent can go up to £900.","zh":"租金最高可到900英镑。","source":"supplemental"},{"en":"Prices go up to £2,000 in the city centre.","zh":"市中心价格高达2000英镑。","source":"supplemental"}]},{"id":"rentals-p-13","term":"for the right place","type":"phrase","sourceOrder":72,"zh":"如果房源确实合适","pos":"短语／语块","ipa":"fɔː ðə raɪt pleɪs","stars":3,"note":"讲义形式：for the right place。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, we'd like to stay under six hundred pounds if possible, but we could go up to six hundred and fifty for the right place.","zh":"我们希望尽量控制在600英镑以下，但房子合适的话最多可以到650英镑。","source":"original","number":45},{"en":"I would pay more for the right place.","zh":"房源合适我愿意多付。","source":"supplemental"},{"en":"We can wait another week for the right place.","zh":"为了合适的房子我们可以再等一周。","source":"supplemental"},{"en":"Location matters for the right place.","zh":"找到合适房子时位置很重要。","source":"supplemental"}]},{"id":"rentals-p-14","term":"come back to","type":"phrase","sourceOrder":73,"zh":"重新谈到某话题","pos":"短语／语块","ipa":"kʌm bæk tə","stars":3,"note":"讲义形式：come back to。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, coming back to the bedrooms, they have to be doubles, both of them.","zh":"说回卧室，两间都必须是双人卧室。","source":"original","number":48},{"en":"Can we come back to the bedrooms?","zh":"能再谈谈卧室吗？","source":"supplemental"},{"en":"I will come back to the rent later.","zh":"稍后我再谈租金。","source":"supplemental"},{"en":"Let us come back to that question.","zh":"我们再回到那个问题。","source":"supplemental"}]},{"id":"rentals-p-15","term":"have to be","type":"phrase","sourceOrder":74,"zh":"必须是/处于某状态","pos":"短语／语块","ipa":"hæv tə biː","stars":2,"note":"讲义形式：have to be。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, coming back to the bedrooms, they have to be doubles, both of them.","zh":"说回卧室，两间都必须是双人卧室。","source":"original","number":48},{"en":"Both rooms have to be doubles.","zh":"两间房都必须是双人间。","source":"supplemental"},{"en":"The kitchen has to be large.","zh":"厨房必须够大。","source":"supplemental"},{"en":"The information has to be accurate.","zh":"信息必须准确。","source":"supplemental"}]},{"id":"rentals-p-16","term":"both of them","type":"phrase","sourceOrder":75,"zh":"两者都","pos":"短语／语块","ipa":"bəʊθ əv ðəm","stars":2,"note":"讲义形式：both of them。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, coming back to the bedrooms, they have to be doubles, both of them.","zh":"说回卧室，两间都必须是双人卧室。","source":"original","number":48},{"en":"Both of them need a desk.","zh":"两者都需要书桌。","source":"supplemental"},{"en":"Both of them are furnished.","zh":"两间都带家具。","source":"supplemental"},{"en":"I visited both of them yesterday.","zh":"昨天我两处都看了。","source":"supplemental"}]},{"id":"rentals-p-17","term":"straight away","type":"phrase","sourceOrder":76,"zh":"马上；立刻","pos":"短语／语块","ipa":"streɪt əˈweɪ","stars":2,"note":"讲义形式：straight away。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"So are you looking for something straight away?","zh":"那么，您想立刻入住吗？","source":"original","number":52},{"en":"I need to move straight away.","zh":"我需要立刻搬家。","source":"supplemental"},{"en":"Please call me straight away.","zh":"请马上给我打电话。","source":"supplemental"},{"en":"The agent replied straight away.","zh":"中介立即回复了。","source":"supplemental"}]},{"id":"rentals-p-18","term":"as soon as possible","type":"phrase","sourceOrder":77,"zh":"尽快","pos":"短语／语块","ipa":"æz suːn æz ˈpɒsəbl","stars":2,"note":"讲义形式：as soon as possible。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, as soon as possible, yes.","zh":"是的，越快越好。","source":"original","number":54},{"en":"We want to move as soon as possible.","zh":"我们希望尽快搬家。","source":"supplemental"},{"en":"Please send the contract as soon as possible.","zh":"请尽快发送合同。","source":"supplemental"},{"en":"I will get back to you as soon as possible.","zh":"我会尽快回复你。","source":"supplemental"}]},{"id":"rentals-p-19","term":"at the earliest","type":"phrase","sourceOrder":78,"zh":"最早","pos":"短语／语块","ipa":"æt ðə ˈɜːliəst","stars":2,"note":"讲义形式：at the earliest。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, it's October the seventeenth today, so we're probably looking at November the first at the earliest.","zh":"今天是10月17日，因此最早可能是11月1日。","source":"original","number":55},{"en":"The flat is available next Monday at the earliest.","zh":"这套公寓最早下周一可入住。","source":"supplemental"},{"en":"We can view it at the earliest on Friday.","zh":"我们最早周五能看房。","source":"supplemental"},{"en":"The repairs will finish in June at the earliest.","zh":"维修最早六月完成。","source":"supplemental"}]},{"id":"rentals-p-20","term":"put down","type":"phrase","sourceOrder":79,"zh":"记下；登记","pos":"短语／语块","ipa":"pʊt daʊn","stars":4,"note":"讲义形式：put down。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, I'd have preferred something in October, but okay, let's put that date down for now.","zh":"我原本更希望10月份，但好吧，先把那个日期记下来。","source":"original","number":57},{"en":"Let us put down 1 November.","zh":"我们先记11月1日。","source":"supplemental"},{"en":"I put down my new address.","zh":"我登记了新地址。","source":"supplemental"},{"en":"The agent put down our requirements.","zh":"中介记下了我们的需求。","source":"supplemental"}]},{"id":"rentals-p-21","term":"for now","type":"phrase","sourceOrder":80,"zh":"暂时；目前先这样","pos":"短语／语块","ipa":"fɔː naʊ","stars":2,"note":"讲义形式：for now。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, I'd have preferred something in October, but okay, let's put that date down for now.","zh":"我原本更希望10月份，但好吧，先把那个日期记下来。","source":"original","number":57},{"en":"Let us keep that date for now.","zh":"日期暂时先这样。","source":"supplemental"},{"en":"For now, we will stay with friends.","zh":"目前我们先住朋友家。","source":"supplemental"},{"en":"That is enough information for now.","zh":"暂时这些信息就够了。","source":"supplemental"}]},{"id":"rentals-p-22","term":"be worried about","type":"phrase","sourceOrder":81,"zh":"担心；在意","pos":"短语／语块","ipa":"biː ˈwʌrid əˈbaʊt","stars":4,"note":"讲义形式：be worried about。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, our last flat had a garage, but actually we never used it, so I'm not really worried about that.","zh":"之前的公寓有车库，但我们从未使用，所以我并不在意车库。","source":"original","number":60},{"en":"I am not worried about parking.","zh":"我不在意停车问题。","source":"supplemental"},{"en":"She is worried about the cost.","zh":"她担心费用。","source":"supplemental"},{"en":"Do not worry about the garage.","zh":"不用担心车库。","source":"supplemental"}]},{"id":"rentals-p-23","term":"if possible","type":"phrase","sourceOrder":82,"zh":"如果可以","pos":"短语／语块","ipa":"ɪf ˈpɒsəbl","stars":2,"note":"讲义形式：if possible。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"But we'd like a balcony if possible.","zh":"但如果可以，我们想要一个阳台。","source":"original","number":61},{"en":"We would like a balcony if possible.","zh":"如果可以，我们想要阳台。","source":"supplemental"},{"en":"Please contact me today if possible.","zh":"可以的话今天联系我。","source":"supplemental"},{"en":"Choose a quiet room if possible.","zh":"可以的话选安静房间。","source":"supplemental"}]},{"id":"rentals-p-24","term":"shut in","type":"phrase","sourceOrder":83,"zh":"困在室内；封闭","pos":"短语／语块","ipa":"ʃʌt ɪn","stars":4,"note":"讲义形式：shut in。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"It's nice not to be too shut in.","zh":"房子别让人觉得太封闭会更舒服。","source":"original","number":62},{"en":"I feel shut in without a window.","zh":"没有窗户我觉得很憋闷。","source":"supplemental"},{"en":"A balcony keeps the room from feeling shut in.","zh":"阳台让房间不那么封闭。","source":"supplemental"},{"en":"He was shut in the office all day.","zh":"他整天闷在办公室里。","source":"supplemental"}]},{"id":"rentals-p-25","term":"have use of","type":"phrase","sourceOrder":84,"zh":"可使用；享有使用权","pos":"短语／语块","ipa":"hæv juːs əv","stars":4,"note":"讲义形式：have use of。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"But of course, if you're in an older property, you might have use of a garden.","zh":"不过如果住在较旧的房屋，您也许可以使用花园。","source":"original","number":66},{"en":"Tenants have use of a shared garden.","zh":"租客可以使用共享花园。","source":"supplemental"},{"en":"You will have use of the laundry room.","zh":"你可以使用洗衣房。","source":"supplemental"},{"en":"Residents have use of the gym.","zh":"住户可以使用健身房。","source":"supplemental"}]},{"id":"rentals-p-26","term":"a possible alternative","type":"phrase","sourceOrder":85,"zh":"可行的替代选择","pos":"短语／语块","ipa":"ə ˈpɒsəbl ɔːlˈtɜːnətɪv","stars":3,"note":"讲义形式：a possible alternative。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Would that be a possible alternative?","zh":"这个能作为替代选择吗？","source":"original","number":67},{"en":"A garden is a possible alternative.","zh":"花园是可行替代。","source":"supplemental"},{"en":"Could we discuss a possible alternative?","zh":"我们能讨论一个替代方案吗？","source":"supplemental"},{"en":"A bus stop may be a possible alternative.","zh":"公交站可能是替代选择。","source":"supplemental"}]},{"id":"rentals-p-27","term":"either of those","type":"phrase","sourceOrder":86,"zh":"两者中任何一个","pos":"短语／语块","ipa":"ˈaɪðə əv ðəʊz","stars":4,"note":"讲义形式：either of those。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Either of those would be good.","zh":"这两种有任何一种都可以。","source":"original","number":69},{"en":"Either of those dates is fine.","zh":"两个日期哪天都行。","source":"supplemental"},{"en":"Either of those rooms would work.","zh":"两个房间任选其一都可以。","source":"supplemental"},{"en":"We would accept either of those options.","zh":"这两个选项我们都可以接受。","source":"supplemental"}]},{"id":"rentals-p-28","term":"off-street parking","type":"phrase","sourceOrder":87,"zh":"路外/院内专用停车位","pos":"短语／语块","ipa":"ˌɒf ˈstriːt ˈpɑːkɪŋ","stars":4,"note":"讲义形式：off-street parking。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Would you want off-street parking?","zh":"您需要路外停车位（不直接占用街道路边的停车位）吗？","source":"original","number":71},{"en":"The building offers off-street parking.","zh":"这栋楼提供非路边停车位。","source":"supplemental"},{"en":"Off-street parking is included in the rent.","zh":"租金包含专用停车位。","source":"supplemental"},{"en":"We do not need off-street parking.","zh":"我们不需要路外停车位。","source":"supplemental"}]},{"id":"rentals-p-29","term":"not too far from","type":"phrase","sourceOrder":88,"zh":"距离……不太远","pos":"短语／语块","ipa":"nɒt tuː fɑː frəm","stars":2,"note":"讲义形式：not too far from。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible.","zh":"不，停车不重要，但如果能住在离车站不太远的地方就好。","source":"original","number":72},{"en":"The flat is not too far from a station.","zh":"这套房离车站不太远。","source":"supplemental"},{"en":"Our office is not too far from here.","zh":"我们办公室离这里不远。","source":"supplemental"},{"en":"Choose a school not too far from home.","zh":"选择一所离家不太远的学校。","source":"supplemental"}]},{"id":"rentals-p-30","term":"not essential","type":"phrase","sourceOrder":89,"zh":"并非必须","pos":"短语／语块","ipa":"nɒt ɪˈsenʃəl","stars":2,"note":"讲义形式：not essential。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"But it's not essential.","zh":"但这不是必需条件。","source":"original","number":73},{"en":"A garage is not essential.","zh":"车库并非必要。","source":"supplemental"},{"en":"Being near a station is not essential.","zh":"靠近车站不是硬性要求。","source":"supplemental"},{"en":"A separate dining room is not essential.","zh":"独立餐厅并非必须。","source":"supplemental"}]},{"id":"rentals-p-31","term":"tend to eat","type":"phrase","sourceOrder":90,"zh":"通常/往往会做","pos":"短语／语块","ipa":"tend tə iːt","stars":3,"note":"讲义形式：tend to do。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that.","zh":"我们通常在厨房吃饭，所以如果厨房足够大，能让我们在那里用餐，就很好。","source":"original","number":80},{"en":"We tend to eat in the kitchen.","zh":"我们通常在厨房吃饭。","source":"supplemental"},{"en":"Students tend to choose cheaper flats.","zh":"学生往往选便宜公寓。","source":"supplemental"},{"en":"Rents tend to rise in summer.","zh":"租金通常在夏季上涨。","source":"supplemental"}]},{"id":"rentals-p-32","term":"large enough for us to eat","type":"phrase","sourceOrder":91,"zh":"足够大，供……做……","pos":"短语／语块","ipa":"lɑːdʒ ɪˈnʌf fɔː ʌs tə iːt","stars":4,"note":"讲义形式：large enough for ... to ...。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that.","zh":"我们通常在厨房吃饭，所以如果厨房足够大，能让我们在那里用餐，就很好。","source":"original","number":80},{"en":"The kitchen is large enough for us to eat in.","zh":"厨房够大，可以在里面吃饭。","source":"supplemental"},{"en":"The room is large enough for four people to work.","zh":"这房间够四个人工作。","source":"supplemental"},{"en":"Is the balcony large enough for a small table?","zh":"阳台够放一张小桌子吗？","source":"supplemental"}]},{"id":"rentals-p-33","term":"make a note of it anyway","type":"phrase","sourceOrder":92,"zh":"即使如此还是记下它","pos":"短语／语块","ipa":"meɪk ə nəʊt əv ɪt ˈeniweɪ","stars":3,"note":"讲义形式：make a note of it anyway。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"That might be difficult, but I'll make a note of it anyway.","zh":"这也许有点难满足，但我还是会记下来。","source":"original","number":81},{"en":"It may be difficult, but I will make a note of it anyway.","zh":"虽然可能有困难，我还是会记录。","source":"supplemental"},{"en":"Please make a note of it anyway.","zh":"无论如何请记下来。","source":"supplemental"},{"en":"The agent made a note of our preference anyway.","zh":"中介仍记下了我们的偏好。","source":"supplemental"}]},{"id":"rentals-p-34","term":"be looking at","type":"phrase","sourceOrder":93,"zh":"考虑；预计（时间/方案）","pos":"短语／语块","ipa":"biː ˈlʊkɪŋ æt","stars":4,"note":"讲义形式：be looking at。听写以原句实际词形为准，模板已具体化。","paragraph":"听力原文","examples":[{"en":"Well, it's October the seventeenth today, so we're probably looking at November the first at the earliest.","zh":"今天是10月17日，因此最早可能是11月1日。","source":"original","number":55},{"en":"We are looking at a move in November.","zh":"我们考虑十一月搬家。","source":"supplemental"},{"en":"They are looking at two apartments.","zh":"他们正在考虑两套公寓。","source":"supplemental"},{"en":"We may be looking at a higher rent.","zh":"我们可能面临更高租金。","source":"supplemental"}]}],"sentences":[{"en":"You will hear a telephone conversation between a man who wants to rent an apartment and an agent at a property rental service.","zh":"你将听到一位想租公寓的男士与房屋租赁服务机构的一名中介之间的电话对话。","speaker":"考官","paragraph":"听力原文","note":"主干 You will hear a telephone conversation；between...and... 标识双方；who wants... 修饰 a man。\n开场直接告知场景：租房咨询；预判会出现姓名、地址、电话和房屋条件。"},{"en":"First, you have some time to look at questions one to five.","zh":"首先，你有时间查看第1至5题。","speaker":"考官","paragraph":"听力原文","note":"have time to do sth＝有时间做某事；questions one to five 表示题号范围。\n预读只关注空格旁的名词与标签。"},{"en":"Now listen carefully and answer questions one to five.","zh":"现在仔细听，回答第1至5题。","speaker":"考官","paragraph":"听力原文","note":"listen 和 answer 为并列祈使句。\n正式答题开始的信号。"},{"en":"Good morning, AA Property.","zh":"早上好，这里是AA房产。","paragraph":"听力原文","note":"电话接听中的省略句，完整可理解为 This is AA Property speaking。\n机构名称通常不是本题空格，不必抄写。"},{"en":"Can I help you?","zh":"请问有什么可以帮您？","paragraph":"听力原文","note":"Can I...？用于礼貌询问。\n电话开场固定句，不是答案。"},{"en":"Yes.","zh":"是的。","paragraph":"听力原文","note":"单词级回应，表示准备提出需求。\n快速过渡，不必逐字翻译。"},{"en":"Good morning.","zh":"早上好。","paragraph":"听力原文","note":"寒暄用语。\n无填空点。"},{"en":"I'm looking for an apartment to rent.","zh":"我正在找一套要租的公寓。","paragraph":"听力原文","note":"be looking for＝寻找；to rent 为后置不定式，修饰 apartment。\napartment＝flat；租房场景核心名词。"},{"en":"Okay.","zh":"好的。","paragraph":"听力原文","note":"话轮回应。\n关注下一问。"},{"en":"Is that here in Birmingham?","zh":"是在伯明翰这里吗？","paragraph":"听力原文","note":"Is that...？确认位置；here in Birmingham 表示目的城市。\n题目已经给 Birmingham，是定位线索。"},{"en":"That's right.","zh":"没错。","paragraph":"听力原文","note":"That's right 确认对方的信息。\n确认性质比回答长短重要。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"话轮标记，用于进入登记环节。\n预期接下来会快速出现个人信息。"},{"en":"I'll just take some personal details, if I may.","zh":"我想先记录一些个人信息，可以吗？","paragraph":"听力原文","note":"I'll just...是礼貌缓和；if I may＝如果可以的话。\n提示 personal details 栏即将开始。"},{"en":"So if I can just take your name.","zh":"那我先记一下您的姓名。","paragraph":"听力原文","note":"if I can... 是省略的礼貌请求形式。\n姓名 Kevin Walker 已在题目中，利用它同步进度。"},{"en":"Kevin Walker.","zh":"凯文·沃克。","paragraph":"听力原文","note":"姓名专有名词。\n题目已给出姓名；不必在录音中停留。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"确认登记完成。\n下一字段即将出现。"},{"en":"And can I have your present address, please?","zh":"请问能告诉我您目前的住址吗？","paragraph":"听力原文","note":"present 作形容词＝目前的；Can I have...？礼貌索取。\n第1题定位：address；切记 present ≠ permanent。"},{"en":"Well, we're staying with friends at present, so the address is three five four Forest Road.","zh":"我们现在暂住在朋友家，所以地址是354 Forest Road。","paragraph":"听力原文","note":"be staying 为现在进行时，表临时居住；at present＝目前；so 引出地址。\n【Q1】题目 ___ Road, West Bromwich 已印 Road，应填 Forest；354 是门牌号不是路名。"},{"en":"Is that Forest with one R?","zh":"Forest 是只有一个字母 R，对吗？","paragraph":"听力原文","note":"with one R 用于拼写核查。\n【Q1】后续二次确认 Forest（只有一个 r），注意不要误写 Forrest。"},{"en":"That's right.","zh":"没错。","paragraph":"听力原文","note":"确认拼写。\n已核实答案后立刻看下一个空。"},{"en":"And that's in West Bromwich.","zh":"地址在 West Bromwich。","paragraph":"听力原文","note":"in 表地点；that's 指前述地址。\nWest Bromwich 已印在题干，不需要写入空格。"},{"en":"I'm afraid I don't know the postcode.","zh":"恐怕我不知道邮政编码。","paragraph":"听力原文","note":"I'm afraid... 不是“害怕”，而是礼貌表达遗憾；post code / postcode。\n邮编没问，跳过即可。"},{"en":"That's okay.","zh":"没关系。","paragraph":"听力原文","note":"接受信息缺失。\n即将换字段。"},{"en":"And a contact phone number.","zh":"再请提供联系电话。","paragraph":"听力原文","note":"省略祈使问句，完整可理解为 And can I have a contact phone number?\n【Q2】phone number 信号一出现，准备按块记数字。"},{"en":"Oh seven eight one seven.","zh":"0、7、8、1、7。","paragraph":"听力原文","note":"oh 在电话号码中代表数字 0，而非惊叹词。\n【Q2】第一块 07817；先写数字，别逐字翻成中文。"},{"en":"Nine eight three six O two.","zh":"9、8、3、6、0、2。","paragraph":"听力原文","note":"字母 O 在号码读法中代表数字 0；数字读音按个串联。\n【Q2】第二块 983602；最终 07817983602，共11位。"},{"en":"Lovely.","zh":"好的。","paragraph":"听力原文","note":"此处 lovely 表示“很好/收到了”，不是“可爱”。\n换字段提示。"},{"en":"And if I could just ask your occupation.","zh":"如果方便的话，我想问一下您的职业。","paragraph":"听力原文","note":"if I could just... 表委婉请求；occupation＝职业。\n【Q3】occupation 指客户的职业，非配偶职业。"},{"en":"Certainly.","zh":"当然可以。","paragraph":"听力原文","note":"同意回答的固定用语。\n无答案。"},{"en":"I'm a dentist and my wife's a teacher, but she's at home at present looking after the children.","zh":"我是牙医，我妻子是教师，但她目前在家照顾孩子。","paragraph":"听力原文","note":"and 连接两职业；but 对比妻子目前状态；looking after... 为现在分词补充动作。\n【Q3】应填 dentist；teacher 是典型近邻干扰，注意 my / my wife's。"},{"en":"Okay.","zh":"好的。","paragraph":"听力原文","note":"回应。\n看中介是否补充限定。"},{"en":"So I'll just put your occupation.","zh":"那我就只登记您的职业。","paragraph":"听力原文","note":"put 在表格登记语境＝填写/记录；your 强调被登记者。\n【Q3】确认只填 dentist，而非 teacher。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"过渡信号。\npersonal details 结束。"},{"en":"Well, now I'll take some details about the kind of property you're looking for.","zh":"现在我来记录一些有关您所寻找的房产类型的信息。","paragraph":"听力原文","note":"the kind of property (that) you're looking for 含省略关系代词的定语从句。\n即将切换到房屋要求小标题。"},{"en":"You said you're looking for an apartment, is that right?","zh":"您说想找一套公寓，是吗？","paragraph":"听力原文","note":"You said... 报述既有信息；is that right? 用于核实。\napartment＝flat，同义词互换。"},{"en":"Yeah.","zh":"是的。","paragraph":"听力原文","note":"非正式确认。\n准备数房间数。"},{"en":"Okay.","zh":"好的。","paragraph":"听力原文","note":"话轮承接。\n下一问有用。"},{"en":"So how many bedrooms do you want?","zh":"那么您想要几间卧室？","paragraph":"听力原文","note":"how many + 可数名词复数；bedrooms＝卧室。\ntwo-bedroom 题干提供数字，可据此判断后文 doubles 的复数。"},{"en":"Two.","zh":"两间。","paragraph":"听力原文","note":"回答数量，省略 bedrooms。\n题目已经给 a two-bedroom...，不必填写 two。"},{"en":"And did you want it furnished?","zh":"那您希望是带家具的吗？","paragraph":"听力原文","note":"furnished 为形容词/过去分词，指房子附家具；did you want... 是礼貌询问。\n【Q4】此处 furnished 是提问选项，不能直接写。"},{"en":"No, unfurnished.","zh":"不，要不带家具的。","paragraph":"听力原文","note":"否定 No + 纠正目标词 unfurnished；un- 表反义前缀。\n【Q4】正确填 unfurnished；把否定后的词作为最终选择。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"登记回应。\n下一句只是解释。"},{"en":"Well, that gives you quite a bit more choice, so that's good.","zh":"这样会让您有更多选择，所以不错。","paragraph":"听力原文","note":"quite a bit more＝多出不少；choice 为不可数集合义。\n这句确认不带家具的房源可选面更多。"},{"en":"And what's the maximum rent you'd be prepared to pay?","zh":"您愿意支付的最高租金是多少？","paragraph":"听力原文","note":"you'd be prepared to pay 修饰 rent；be prepared to＝愿意；maximum＝最高。\n最高预算和理想预算可能不同。"},{"en":"Well, we'd like to stay under six hundred pounds if possible, but we could go up to six hundred and fifty for the right place.","zh":"我们希望尽量控制在600英镑以下，但房子合适的话最多可以到650英镑。","paragraph":"听力原文","note":"under...＝低于；but 引出让步后上限；go up to＝高达。\n题目已给 maximum £650，注意 600 是偏好、650 是上限。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"确认。\n转向附加要求。"},{"en":"So do you have any other definite requirements?","zh":"还有其他明确、必须满足的要求吗？","paragraph":"听力原文","note":"definite＝明确的；requirements＝要求。\n关键词 requirements 标明下一题是硬性条件。"},{"en":"Well, coming back to the bedrooms, they have to be doubles, both of them.","zh":"说回卧室，两间都必须是双人卧室。","paragraph":"听力原文","note":"coming back to＝回到话题；have to＝必须；doubles 为名词复数，指双人卧室；both of them 强化“两间都”。\n【Q5】必须填 doubles（复数），不是 double。"},{"en":"Okay, I'll make a note of that.","zh":"好的，我会把它记录下来。","paragraph":"听力原文","note":"make a note of＝记下；that 指卧室要求。\n硬性要求得到确认。"},{"en":"Before you hear the rest of the conversation, you have some time to look at questions six to ten.","zh":"听接下来的对话前，你有时间查看第6至10题。","speaker":"考官","paragraph":"听力原文","note":"before 引导时间状语从句；the rest of＝其余部分。\n切换答题区间，预读入住时间及设施。"},{"en":"Now listen and answer questions six to ten.","zh":"现在听录音，回答第6至10题。","speaker":"考官","paragraph":"听力原文","note":"并列祈使句。\n第二段开始。"},{"en":"So are you looking for something straight away?","zh":"那么，您想立刻入住吗？","paragraph":"听力原文","note":"straight away＝立刻；something 指可租的房子。\n【Q6】入住日期即将出现，留意建议日期与最后确认。"},{"en":"I assume you are if you're staying with friends.","zh":"我想既然您暂住在朋友家，应该想尽快搬入。","paragraph":"听力原文","note":"assume＝推测；if 提供推断理由。\n中介推断不等于正式入住时间。"},{"en":"Well, as soon as possible, yes.","zh":"是的，越快越好。","paragraph":"听力原文","note":"as soon as possible 为最高程度时间愿望。\n未给具体日期，不急着填。"},{"en":"Well, it's October the seventeenth today, so we're probably looking at November the first at the earliest.","zh":"今天是10月17日，因此最早可能是11月1日。","paragraph":"听力原文","note":"it's + 日期；we're looking at＝考虑/预计；at the earliest＝最早。\n【Q6】10月17日是“今天”，11月1日才是拟入住日期。"},{"en":"Would that be okay?","zh":"这个日期可以吗？","paragraph":"听力原文","note":"Would that be...？用于礼貌征求同意。\n等待最终接受或否定。"},{"en":"Well, I'd have preferred something in October, but okay, let's put that date down for now.","zh":"我原本更希望10月份，但好吧，先把那个日期记下来。","paragraph":"听力原文","note":"I'd have preferred...＝原本更希望（与现实不符的愿望）；but okay 表接受；put down＝记录。\n【Q6】最终同意 November 1；October 只是原本偏好，排除 October 1。"},{"en":"Fine.","zh":"好的。","paragraph":"听力原文","note":"确认落实。\n第6题位置结束。"},{"en":"Now, is there anything else you'd like?","zh":"您还有其他想要的吗？","paragraph":"听力原文","note":"anything else＝别的什么；you'd like 省略宾语关系词。\n进入 optional features（非必需配套设施）。"},{"en":"Well, our last flat had a garage, but actually we never used it, so I'm not really worried about that.","zh":"之前的公寓有车库，但我们从未使用，所以我并不在意车库。","paragraph":"听力原文","note":"last＝之前的；but actually 推翻“需要车库”的猜想；be worried about＝在意。\ngarage 不是第7/8题答案，而是被否定的设施。"},{"en":"But we'd like a balcony if possible.","zh":"但如果可以，我们想要一个阳台。","paragraph":"听力原文","note":"would like＝想要；if possible 表非硬性要求。\n【Q7】明确填 balcony。"},{"en":"It's nice not to be too shut in.","zh":"房子别让人觉得太封闭会更舒服。","paragraph":"听力原文","note":"It's + adj + not to do；shut in＝困在封闭空间、活动受限。\n说明要阳台的原因，而非新设施。"},{"en":"Yes.","zh":"是的。","paragraph":"听力原文","note":"简单应答。\n中介接着给替代选择。"},{"en":"You'll find most modern apartments do have one.","zh":"您会发现大多数现代公寓确实有阳台。","paragraph":"听力原文","note":"do have 中 do 表强调；one 代指 balcony。\n不要把 one 当答案，它是代词。"},{"en":"It's only the converted properties that don't.","zh":"只有改建后的房产才可能没有阳台。","paragraph":"听力原文","note":"It's...that... 为强调句；converted properties＝改造过的房屋；don't 省略 have one。\n区分房屋类型，继续听替代选项。"},{"en":"But of course, if you're in an older property, you might have use of a garden.","zh":"不过如果住在较旧的房屋，您也许可以使用花园。","paragraph":"听力原文","note":"if 条件状语从句；might＝可能；have use of＝有权使用。\n【Q8】第二个设施为 garden。"},{"en":"Would that be a possible alternative?","zh":"这个能作为替代选择吗？","paragraph":"听力原文","note":"alternative＝替代方案；that 指 garden。\n是否接受花园要由客户回答决定。"},{"en":"Oh, yes.","zh":"哦，可以。","paragraph":"听力原文","note":"肯定同意。\n花园成为可接受答案。"},{"en":"Either of those would be good.","zh":"这两种有任何一种都可以。","paragraph":"听力原文","note":"either of those＝两者之一；would be good 表可接受。\n【Q7–8】balcony OR garden，注意不是要求两者同时有。"},{"en":"What about transport?","zh":"交通方面有什么要求？","paragraph":"听力原文","note":"What about...？切换话题。\n第9题站点类答案将出现。"},{"en":"Would you want off-street parking?","zh":"您需要路外停车位（不直接占用街道路边的停车位）吗？","paragraph":"听力原文","note":"off-street＝不在公共道路上的；parking＝停车设施。\n题中中文“路边停车位”不准确；off-street 反而是路外停车。"},{"en":"No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible.","zh":"不，停车不重要，但如果能住在离车站不太远的地方就好。","paragraph":"听力原文","note":"No 否定停车要求；but 改为车站要求；not too far from＝离……不太远。\n【Q9】题干 be near a ___ 对应 not too far from a station；填 station，不是 pool。"},{"en":"But it's not essential.","zh":"但这不是必需条件。","paragraph":"听力原文","note":"essential＝必需的；it 指靠近车站。\n虽非硬性要求，题干 if possible 仍应填 station。"},{"en":"I've got a bike.","zh":"我有自行车。","paragraph":"听力原文","note":"have got＝拥有。\n说明即使不近车站也可以，bike 不是答案。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"登记过渡。\n等待房间配置。"},{"en":"And what else?","zh":"还有什么呢？","paragraph":"听力原文","note":"简短接续问句。\n话题从交通转为室内房间。"},{"en":"You'll want a lounge.","zh":"您会需要一个起居室。","paragraph":"听力原文","note":"lounge 在房屋语境中＝客厅/起居室。\nlounge 不是第10题填空所需的 large ___。"},{"en":"And will you want a separate dining room?","zh":"您是否需要一间独立餐厅？","paragraph":"听力原文","note":"separate＝独立的；dining room＝餐厅。\n【Q10】这是中介提出的可能项，不是客户最终愿望。"},{"en":"Well, not really.","zh":"嗯，不太需要。","paragraph":"听力原文","note":"not really 是委婉否定。\n排除 dining / dining room。"},{"en":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that.","zh":"我们通常在厨房吃饭，所以如果厨房足够大，能让我们在那里用餐，就很好。","paragraph":"听力原文","note":"tend to＝往往；so 说明结果；that 代指 kitchen；large enough for sb to do sth＝足够大供某人做某事。\n【Q10】large kitchen；dining 是干扰项，核心是厨房面积。"},{"en":"That might be difficult, but I'll make a note of it anyway.","zh":"这也许有点难满足，但我还是会记下来。","paragraph":"听力原文","note":"might＝可能；make a note of...＝记下；anyway＝无论如何。\n不改变客户要求，答案仍 kitchen。"},{"en":"Right.","zh":"好的。","paragraph":"听力原文","note":"过渡回应。\n录音已接近结束。"},{"en":"Well, let's have a look at what...","zh":"那我们看看有什么……（录音在此截断）。","paragraph":"听力原文","note":"let's have a look at...＝让我们看一下；what 从句尚未说完。\n文本结尾不是完整句，不自行补写任何房源信息。"}],"questions":[{"number":1,"question":"Address: ___ Road, West Bromwich","answer":"Forest","chosen":"354","focus":"填空在 Road 前，语法期待路名修饰词；354 是门牌号，且 Road 已给出。","mistake":"推测：填空在 Road 前，语法期待路名修饰词；354 是门牌号，且 Road 已给出。","method":"识别地址结构：354（门牌号） + Forest（路名） + Road（道路类型）；预读时在空格上方标“路名”。","evidence":[{"en":"Well, we're staying with friends at present, so the address is three five four Forest Road.","zh":"我们现在暂住在朋友家，所以地址是354 Forest Road。","paragraph":"听力原文","note":"be staying 为现在进行时，表临时居住；at present＝目前；so 引出地址。\n【Q1】题目 ___ Road, West Bromwich 已印 Road，应填 Forest；354 是门牌号不是路名。","highlight":"Forest"},{"en":"Is that Forest with one R?","zh":"Forest 是只有一个字母 R，对吗？","paragraph":"听力原文","note":"with one R 用于拼写核查。\n【Q1】后续二次确认 Forest（只有一个 r），注意不要误写 Forrest。","highlight":"Forest"}],"wrong":true,"type":"表格填空","instruction":"Write ONE WORD AND/OR A NUMBER for each answer.","choices":[]},{"number":2,"question":"Phone: ___","answer":"07817983602","chosen":"07","focus":"只抄前两位，长数字未分块跟上；oh / O 在号码里读作 0。","mistake":"推测：只抄前两位，长数字未分块跟上；oh / O 在号码里读作 0。","method":"记号策略：07817 | 983602（最终合并为 11 位）；在下一题开始前快速点数核验。","evidence":[{"en":"Oh seven eight one seven.","zh":"0、7、8、1、7。","paragraph":"听力原文","note":"oh 在电话号码中代表数字 0，而非惊叹词。\n【Q2】第一块 07817；先写数字，别逐字翻成中文。","highlight":"seven eight"},{"en":"Nine eight three six O two.","zh":"9、8、3、6、0、2。","paragraph":"听力原文","note":"字母 O 在号码读法中代表数字 0；数字读音按个串联。\n【Q2】第二块 983602；最终 07817983602，共11位。","highlight":""}],"wrong":true,"type":"表格填空","instruction":"Write ONE WORD AND/OR A NUMBER for each answer.","choices":[]},{"number":5,"question":"The bedrooms must be ___","answer":"doubles","chosen":"double","focus":"原文将 double 名词化为 doubles（双人卧室），而且两间都要求如此。","mistake":"推测：原文将 double 名词化为 doubles（双人卧室），而且两间都要求如此。","method":"听到 both of them 时核对复数；本题要按录音填 doubles。","evidence":[{"en":"Well, coming back to the bedrooms, they have to be doubles, both of them.","zh":"说回卧室，两间都必须是双人卧室。","paragraph":"听力原文","note":"coming back to＝回到话题；have to＝必须；doubles 为名词复数，指双人卧室；both of them 强化“两间都”。\n【Q5】必须填 doubles（复数），不是 double。","highlight":"doubles"}],"wrong":true,"type":"表格填空","instruction":"Write ONE WORD AND/OR A NUMBER for each answer.","choices":[]},{"number":6,"question":"Date required: ___","answer":"1 November","chosen":"October 1","focus":"混淆当前日期、理想月份及最后确认的入住日期；October 1 未在原文出现。","mistake":"推测：混淆当前日期、理想月份及最后确认的入住日期；October 1 未在原文出现。","method":"画三格：today＝17 Oct / available＝1 Nov / accepted＝1 Nov；日期必须等答复确认。","evidence":[{"en":"Well, it's October the seventeenth today, so we're probably looking at November the first at the earliest.","zh":"今天是10月17日，因此最早可能是11月1日。","paragraph":"听力原文","note":"it's + 日期；we're looking at＝考虑/预计；at the earliest＝最早。\n【Q6】10月17日是“今天”，11月1日才是拟入住日期。","highlight":"November the first"},{"en":"Well, I'd have preferred something in October, but okay, let's put that date down for now.","zh":"我原本更希望10月份，但好吧，先把那个日期记下来。","paragraph":"听力原文","note":"I'd have preferred...＝原本更希望（与现实不符的愿望）；but okay 表接受；put down＝记录。\n【Q6】最终同意 November 1；October 只是原本偏好，排除 October 1。","highlight":""}],"wrong":true,"type":"表格填空","instruction":"Write ONE WORD AND/OR A NUMBER for each answer.","choices":[]},{"number":7,"question":"have a ___ or a ___","answer":"balcony","chosen":"未作答","focus":"没有把非必需但明确提出的设施对应到第一个空。","mistake":"推测：没有把非必需但明确提出的设施对应到第一个空。","method":"读题时看到 or，提前在两个空中标“设施A”“设施B”；立即写 balcony。","evidence":[{"en":"But we'd like a balcony if possible.","zh":"但如果可以，我们想要一个阳台。","paragraph":"听力原文","note":"would like＝想要；if possible 表非硬性要求。\n【Q7】明确填 balcony。","highlight":"balcony"}],"wrong":true,"type":"表格填空","instruction":"Write ONE WORD AND/OR A NUMBER for each answer.","choices":[]},{"number":9,"question":"be near a ___","answer":"station","chosen":"pool","focus":"没有锁定 station，填入原文未出现的 pool；可能受到对场景的自我联想干扰。","mistake":"推测：没有锁定 station，填入原文未出现的 pool；可能受到对场景的自我联想干扰。","method":"near a＝not too far from a；题干 transport 给出语义场，应等听到地点词。","evidence":[{"en":"No, parking doesn't matter, but it'd be good to have somewhere not too far from a station if possible.","zh":"不，停车不重要，但如果能住在离车站不太远的地方就好。","paragraph":"听力原文","note":"No 否定停车要求；but 改为车站要求；not too far from＝离……不太远。\n【Q9】题干 be near a ___ 对应 not too far from a station；填 station，不是 pool。","highlight":"station"}],"wrong":true,"type":"表格填空","instruction":"Write ONE WORD AND/OR A NUMBER for each answer.","choices":[]},{"number":10,"question":"have a large ___","answer":"kitchen","chosen":"dining","focus":"听到 dining 就停笔，忽略 Not really 和后文真正要求的 large kitchen。","mistake":"推测：听到 dining 就停笔，忽略 Not really 和后文真正要求的 large kitchen。","method":"严格执行“问项→拒绝→最终需求”：dining room 被拒；kitchen 被明确要求够大。","evidence":[{"en":"And will you want a separate dining room?","zh":"您是否需要一间独立餐厅？","paragraph":"听力原文","note":"separate＝独立的；dining room＝餐厅。\n【Q10】这是中介提出的可能项，不是客户最终愿望。","highlight":""},{"en":"Well, our last flat had a garage, but actually we never used it, so I'm not really worried about that.","zh":"之前的公寓有车库，但我们从未使用，所以我并不在意车库。","paragraph":"听力原文","note":"last＝之前的；but actually 推翻“需要车库”的猜想；be worried about＝在意。\ngarage 不是第7/8题答案，而是被否定的设施。","highlight":""},{"en":"We tend to eat in the kitchen, so it'd be good if that was large enough for us to do that.","zh":"我们通常在厨房吃饭，所以如果厨房足够大，能让我们在那里用餐，就很好。","paragraph":"听力原文","note":"tend to＝往往；so 说明结果；that 代指 kitchen；large enough for sb to do sth＝足够大供某人做某事。\n【Q10】large kitchen；dining 是干扰项，核心是厨房面积。","highlight":"kitchen"}],"wrong":true,"type":"表格填空","instruction":"Write ONE WORD AND/OR A NUMBER for each answer.","choices":[]}],"examples":[]};
